import { useId, useState } from 'react';
import data from '../../generated/credits.json';

/**
 * Settings → About → Open-source software. The data is generated by `scripts/credits/generate.mjs`
 * (`pnpm credits`) from the package.json files, node_modules and `acknowledgements.json`, and loaded
 * lazily (it carries every license text), so it never weighs on the first paint.
 */
interface PackageCredit {
  name: string;
  version: string;
  license: string;
  author: string | null;
  url: string;
  usedBy: string[];
  via: string | null;
  note: string | null;
  licenseText: string | null;
  noticeText: string | null;
}

interface AdaptedCredit {
  name: string;
  url: string;
  license: string;
  copyright: string;
  files: { path: string; what: string }[];
  design?: string;
  licenseText: string;
}

interface CreditsData {
  runtime: PackageCredit[];
  dev: PackageCredit[];
  programs: { name: string; url: string; license: string; description: string }[];
  adapted: AdaptedCredit[];
  inspiration: string[];
}

const credits = data as CreditsData;

export function Credits() {
  const [filter, setFilter] = useState('');
  const filterId = useId();
  const query = filter.trim().toLowerCase();
  const match = (p: PackageCredit) =>
    query === '' ||
    p.name.toLowerCase().includes(query) ||
    p.license.toLowerCase().includes(query) ||
    (p.author ?? '').toLowerCase().includes(query);
  const runtime = credits.runtime.filter(match);
  const dev = credits.dev.filter(match);

  return (
    <section aria-labelledby={`${filterId}-title`} className="mt-6 border-t border-line pt-4">
      <h4 id={`${filterId}-title`} className="text-xs font-semibold">
        Open-source software
      </h4>
      <p className="mt-0.5 text-[11px] text-muted">
        octopus-diff is built on the work of these projects and the people who maintain them. Thank
        you. Each entry has its license.
      </p>

      <h5 className="od-label mt-4 mb-1">Code adapted from other projects</h5>
      <ul className="text-xs">
        {credits.adapted.map((a) => (
          <li key={a.name} className="border-b border-line py-1.5 last:border-0">
            <details className="group">
              <summary className="flex cursor-pointer list-none items-center gap-2 [&::-webkit-details-marker]:hidden">
                <Chevron />
                <span className="font-medium">{a.name}</span>
                <span className="od-chip">{a.license}</span>
              </summary>
              <div className="mt-1.5 space-y-1 pl-[18px] text-[11px] text-muted">
                <p>
                  {a.copyright} · <ExternalLink href={a.url} />
                </p>
                <ul className="list-disc pl-4">
                  {a.files.map((f) => (
                    <li key={f.path}>
                      <span className="font-mono text-fg">{f.path}</span>: {f.what}
                    </li>
                  ))}
                  {a.design && <li>{a.design}</li>}
                </ul>
                <LicenseText text={a.licenseText} />
              </div>
            </details>
          </li>
        ))}
      </ul>

      <h5 className="od-label mt-4 mb-1">Programs it runs</h5>
      <ul className="text-xs">
        {credits.programs.map((p) => (
          <li key={p.name} className="py-1">
            <span className="font-medium">{p.name}</span>{' '}
            <span className="od-chip ml-1">{p.license}</span>
            <p className="mt-0.5 text-[11px] text-muted">
              {p.description} <ExternalLink href={p.url} />
            </p>
          </li>
        ))}
      </ul>

      <div className="mt-4 flex items-center gap-2">
        <label htmlFor={filterId} className="sr-only">
          Filter packages
        </label>
        <input
          id={filterId}
          type="search"
          value={filter}
          onChange={(e) => setFilter(e.target.value)}
          placeholder="Filter packages by name, license or author"
          className="od-input w-full"
        />
      </div>

      <PackageList
        title="Shipped with octopus-diff"
        hint="Runs in the daemon or is bundled into this UI, including what those packages pull in."
        packages={runtime}
        total={credits.runtime.length}
        shipped
      />
      <PackageList
        title="Development tools"
        hint="Used to build and test octopus-diff; not shipped."
        packages={dev}
        total={credits.dev.length}
      />

      <h5 className="od-label mt-4 mb-1">Inspiration</h5>
      <p className="text-[11px] text-muted">
        Ideas, no code: {credits.inspiration.join(', ')}, which explored multi-repository, worktree
        and agent-review views before us.
      </p>
    </section>
  );
}

function PackageList({
  title,
  hint,
  packages,
  total,
  shipped = false,
}: {
  title: string;
  hint: string;
  packages: PackageCredit[];
  total: number;
  shipped?: boolean;
}) {
  return (
    <>
      <h5 className="od-label mt-4">
        {title}{' '}
        <span className="font-normal text-faint">
          {packages.length === total ? total : `${packages.length} of ${total}`}
        </span>
      </h5>
      <p className="mb-1 text-[11px] text-faint">{hint}</p>
      {packages.length === 0 ? (
        <p className="py-1 text-[11px] text-muted">No package matches.</p>
      ) : (
        <ul aria-label={title} className="text-xs">
          {packages.map((p) => (
            <li
              key={`${p.name}@${p.version}`}
              data-package={p.name}
              className="border-b border-line py-1 last:border-0"
            >
              <PackageRow pkg={p} shipped={shipped} />
            </li>
          ))}
        </ul>
      )}
    </>
  );
}

function PackageRow({ pkg, shipped }: { pkg: PackageCredit; shipped: boolean }) {
  const origin =
    pkg.usedBy.length > 0
      ? pkg.usedBy.map((u) => u.replace(/^(apps|packages|tools)\//, '')).join(', ')
      : `via ${pkg.via}`;
  return (
    <details className="group">
      <summary className="flex cursor-pointer list-none items-center gap-2 [&::-webkit-details-marker]:hidden">
        <Chevron />
        <span className="min-w-0 truncate font-mono">{pkg.name}</span>
        <span className="shrink-0 text-[11px] text-faint">{pkg.version}</span>
        <span className="od-chip shrink-0">{pkg.license}</span>
        <span className="ml-auto min-w-0 truncate text-[11px] text-faint">{origin}</span>
      </summary>
      <div className="mt-1.5 space-y-1 pb-1 pl-[18px] text-[11px] text-muted">
        <p>
          {pkg.author && <>{pkg.author} · </>}
          <ExternalLink href={pkg.url} />
        </p>
        {pkg.note && <p>{pkg.note}</p>}
        {pkg.licenseText ? (
          <LicenseText text={pkg.licenseText} />
        ) : (
          <p className="text-faint">
            {shipped
              ? `The package ships no license file; it is published under ${pkg.license}.`
              : `Published under ${pkg.license}.`}
          </p>
        )}
        {pkg.noticeText && <LicenseText text={pkg.noticeText} label="NOTICE" />}
      </div>
    </details>
  );
}

function LicenseText({ text, label }: { text: string; label?: string }) {
  return (
    <div>
      {label && <p className="mb-0.5 text-faint">{label}</p>}
      <pre className="od-scroll max-h-56 overflow-auto rounded-md border border-line bg-canvas p-2 font-mono text-[10.5px] leading-snug whitespace-pre-wrap text-muted">
        {text}
      </pre>
    </div>
  );
}

function Chevron() {
  return (
    <svg
      viewBox="0 0 12 12"
      width="10"
      height="10"
      aria-hidden="true"
      className="shrink-0 text-faint transition-transform group-open:rotate-90"
    >
      <path d="M4 2l4 4-4 4" fill="none" stroke="currentColor" strokeWidth="1.5" />
    </svg>
  );
}

function ExternalLink({ href }: { href: string }) {
  return (
    <a
      href={href}
      target="_blank"
      rel="noreferrer"
      className="text-accent underline decoration-faint underline-offset-2 hover:decoration-current"
    >
      {href.replace(/^https:\/\/(www\.)?/, '')}
    </a>
  );
}
